css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .pal-fila{display: flex; align-items: center; gap: 10px; font-size: 15px; font-weight: 600; margin-bottom: 9px;}
.mz .pal-fila .palabra{flex: 1;}
.mz .pal-fila .caja-cifra{width: 100px; height: 36px; border: 1.5px solid var(--bosque); border-radius: 6px; flex-shrink: 0;}
.mz .leer-fila{display: flex; align-items: center; gap: 12px; margin-bottom: 11px;}
.mz .leer-fila .num-grande{font-size: 24px; font-weight: 700; min-width: 60px;}
.mz .leer-fila .linea-escribir{flex: 1; border-bottom: 1.5px solid var(--bosque); height: 22px;}
.mz .valor-fila{display: flex; align-items: center; gap: 10px; font-size: 16px; font-weight: 600; margin-bottom: 9px; flex-wrap: wrap;}
.mz .valor-fila .num-marcado{font-size: 22px; font-weight: 700; letter-spacing: 2px;}
.mz .valor-fila .num-marcado .destacado{text-decoration: underline; text-underline-offset: 3px;}
.mz .valor-fila .caja-vale{width: 90px; height: 34px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .ap-tabla{border-collapse: collapse;}
.mz .ap-tabla th,.mz .ap-tabla td{border: 1.5px solid var(--bosque); text-align: center;}
.mz .ap-tabla th{font-family: sans-serif; font-size: 11.5px; background: #f3f3f3; padding: 3px 8px;}
.mz .ap-tabla td{height: 36px; width: 110px; font-size: 20px; font-weight: 700;}
.mz .ap-tabla td.dado{background: #f3f3f3;}
